/*
 * A359332  Numbers with arithmetic derivative which is a palindromic prime
 *          number (A002385).
 * https://oeis.org/A359332
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   numbers m such that the arithmetic derivative m′ is a
 *            palindromic prime. The sequence is generated by brute‑force
 *            search because no closed form is known
 * Range:     u8 n <= 2, u16 n <= 27, u32 n <= 44, u64 n <= 44, u128 n <= 44,
 *            big any n
 * Helpers:   build_primes_upto, floor_sqrt, is_palindrome, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

#include "../utils/is_prime_big.h"
#include "../utils/is_palindrome.h"
#include "../utils/build_primes_upto.h"
#include "../utils/floor_sqrt.h"

/* ---- cache for the sequence values --------------------------------- */
static seq_t *seq_cache   = NULL;  /* array of sequence terms           */
static size_t seq_len     = 0;     /* current number of cached terms    */
static size_t seq_cap     = 0;     /* allocated capacity of seq_cache   */

/* ---- array of small primes (uint64_t) ------------------------------ */
static uint64_t *prime_arr  = NULL;    /* prime list                      */
static size_t   prime_cnt   = 0;       /* number of primes in the list    */
static idx_t    prime_limit = 0;       /* highest number for which primes
                                         are guaranteed to exist      */

/* --------------------------------------------------------------------
   Ensure that the array 'prime_arr' contains all primes ≤ limit.
   Existing data are freed and new primes are generated.  The primes
   are used for trial division in the arithmetic‑derivative routine.
-------------------------------------------------------------------- */
static void ensure_prime_limit(idx_t limit)
{
    if (limit <= prime_limit) return;      /* already sufficient */

    if (prime_arr) {
        free(prime_arr);
        prime_arr = NULL;
    }
    /* build_prime_upto allocates the array and sets prime_cnt      */
    build_primes_upto(limit, &prime_arr, &prime_cnt);
    prime_limit = limit;
}

/* --------------------------------------------------------------------
   Compute the arithmetic derivative of n.  The function expects that
   'prime_arr' contains all primes up to √n.
-------------------------------------------------------------------- */
static seq_t arith_deriv(seq_t n)
{
    seq_t orig = n;
    seq_t sum  = 0;
    seq_t temp = n;

    for (size_t i = 0; i < prime_cnt; ++i) {
        uint64_t p = prime_arr[i];
        seq_t pp   = (seq_t)p * (seq_t)p;
        if (pp > temp) break;                 /* no further primes needed */

        int e = 0;
        while (temp % (seq_t)p == (seq_t)0) {
            temp /= (seq_t)p;
            ++e;
        }
        if (e > 0)
            sum += (seq_t)e * (orig / (seq_t)p);
    }

    /* If anything remains, it is a prime factor > √original n */
    if (temp > (seq_t)1)
        sum += (seq_t)1 * (orig / temp);

    return sum;
}

/* --------------------------------------------------------------------
   Append a new term to the sequence cache, increasing its capacity
   if necessary.
-------------------------------------------------------------------- */
static void append_to_cache(seq_t val)
{
    if (seq_len >= seq_cap) {          /* grow the array             */
        size_t new_cap = seq_cap ? seq_cap * 2 : 16;
        seq_t *new_ptr = (seq_t *)realloc(seq_cache,
                                          new_cap * sizeof(seq_t));
        if (!new_ptr) abort();         /* allocation failure         */
        seq_cache = new_ptr;
        seq_cap   = new_cap;
    }
    seq_cache[seq_len++] = val;
}

/* --------------------------------------------------------------------
   Return the n‑th term of A359332 (1‑based).  The function is
   cache‑friendly and can be called in any order.
-------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;              /* undefined, but harmless       */

    static seq_t last_checked = 0;     /* last candidate examined      */

    /* Generate terms until we have at least n of them. */
    while (seq_len < (size_t)n) {
        last_checked += 1;
        seq_t cand = last_checked;

        /* Ensure the prime table covers √cand. */
        seq_t sqrt_cand = floor_sqrt(cand);
        idx_t limit = (idx_t)sqrt_cand; /* fits into idx_t for all relevant cases */
        ensure_prime_limit(limit);

        seq_t d = arith_deriv(cand);
        if (is_prime_big(d) && is_palindrome(d, 10))
            append_to_cache(cand);
    }
    return seq_cache[n - 1];
}
